#!/usr/bin/env bash
# pr-regen.sh FILE...: rebuild generated files over a merged tree (agentctl open-pr, when a ticket's change conflicts
# with the base only in them: the base's copy is checked out first). Exit 2 for a file it cannot rebuild.
#   dirac/docs/support.md                          regenerated by TestSupportDocIsCurrent (needs the corpus)
#   internal/codeshape/testdata/func_ceilings.tsv  the base's rows lowered to the merged tree's measurement; then the
#                                                  ratchets must pass, so a ticket that grows a function still fails
#   dirac/oracle/testdata/repro_table_names.txt    append-only snapshot (TestReproGlobMatchesTable): the base's rows,
#                                                  then the ticket's new ones. The ticket side is PR_REGEN_HEAD (agentctl
#                                                  open-pr sets it), else MERGE_HEAD (a hand merge in progress)
#   dirac/kgen/testdata/acceptance.tsv,            kgen's acceptance pins, re-measured over the merged tree from the
#   dirac/kgen/testdata/build_acceptance.tsv,      base's rows (KGEN_REPIN=1 takes a rise, refuses a fall), then held
#                                                  exact (DIRAC_PIN_STRICT=1): #617 11-17 waited on a resolver seat
#   dirac/kgen/testdata/remspan.tsv                re-pinned with them (TestRememberedSpanCensus; #635 11-17)
set -uo pipefail
for f; do
  case $f in
  dirac/docs/support.md | internal/codeshape/testdata/func_ceilings.tsv | dirac/oracle/testdata/repro_table_names.txt) ;;
  dirac/kgen/testdata/acceptance.tsv | dirac/kgen/testdata/build_acceptance.tsv | dirac/kgen/testdata/remspan.tsv) ;;
  *) echo "pr-regen: $f is not a generated file this script rebuilds"; exit 2 ;;
  dirac/kgen/testdata/acceptance.tsv | dirac/kgen/testdata/build_acceptance.tsv | dirac/kgen/testdata/remspan.tsv)
    [ -z "$pinned" ] || continue
    pinned=1
    source scripts/pr-cards.sh
    "${cap[@]}" env KGEN_REPIN=1 go test -timeout 5m -run "$pins" ./dirac/kgen >/dev/null 2>&1
    "${cap[@]}" env DIRAC_PIN_STRICT=1 go test -timeout 5m -run "$pins" ./dirac/kgen ||
      { echo "pr-regen: kgen acceptance pins did not re-pin (a fall needs a reason: KGEN_REPIN_FALL)"; exit 1; }
    ;;
  esac
done
pins='^(TestCorpusAcceptance|TestSetAcceptance|TestCorpusBuildAcceptance|TestPinTablesParse|TestRememberedSpanCensus|TestStdMetaPoolBuilds)$'
pinned=
cap=(systemd-run --user --scope -q -p MemoryMax=4G -p CPUQuota=400% env GOMAXPROCS=4 GOMEMLIMIT=3GiB)
for f; do
  case $f in
  dirac/docs/support.md)
    source scripts/pr-cards.sh
    "${cap[@]}" env DIRAC_UPDATE_SUPPORT=1 go test -timeout 5m -run '^TestSupportDocIsCurrent$' ./dirac/kgen >/dev/null 2>&1
    "${cap[@]}" go test -timeout 5m -run '^TestSupportDocIsCurrent$' ./dirac/kgen || { echo "pr-regen: support.md did not regenerate"; exit 1; }
    ;;
  internal/codeshape/testdata/func_ceilings.tsv)
    "${cap[@]}" env CODESHAPE_LOWER=1 go test -timeout 5m -run '^TestFuncCeilingsLowerOnly$' ./internal/codeshape >/dev/null 2>&1
    "${cap[@]}" go test -timeout 5m -run '^(TestFuncCeilingsLowerOnly|TestLongFunctionsOnlyShrink|TestComplexFunctionsOnlyShrink)$' ./internal/codeshape ||
      { echo "pr-regen: func_ceilings.tsv lowered, but a function grew past the base's ceiling"; exit 1; }
    ;;
  dirac/oracle/testdata/repro_table_names.txt)
    head=${PR_REGEN_HEAD:-$(git rev-parse -q --verify MERGE_HEAD)}
    [ -n "$head" ] || { echo "pr-regen: $f needs the ticket side (PR_REGEN_HEAD or a merge in progress)"; exit 2; }
    git show "$head:$f" >/dev/null 2>&1 || { echo "pr-regen: $head has no $f"; exit 1; }
    { cat "$f"; git show "$head:$f"; } | awk 'NF && !seen[$0]++' >"$f.regen" && mv "$f.regen" "$f"
    "${cap[@]}" go test -timeout 5m -run '^TestReproGlobMatchesTable$' ./dirac/oracle ||
      { echo "pr-regen: repro_table_names.txt merged, but TestReproGlobMatchesTable fails"; exit 1; }
    ;;
  dirac/kgen/testdata/acceptance.tsv | dirac/kgen/testdata/build_acceptance.tsv | dirac/kgen/testdata/remspan.tsv)
    [ -z "$pinned" ] || continue
    pinned=1
    source scripts/pr-cards.sh
    "${cap[@]}" env KGEN_REPIN=1 go test -timeout 5m -run "$pins" ./dirac/kgen >/dev/null 2>&1
    "${cap[@]}" env DIRAC_PIN_STRICT=1 go test -timeout 5m -run "$pins" ./dirac/kgen ||
      { echo "pr-regen: kgen acceptance pins did not re-pin (a fall needs a reason: KGEN_REPIN_FALL)"; exit 1; }
    ;;
  esac
done
